#include <string.h>
#include <assert.h>
#include "buffer.h"
#include "helpers.h"

void unit_test_buffer_prepend_resize_fails(void) {
    // Setup: create a buffer with small capacity and some content
    char initial_content[] = "world";
    buffer_t *buf = helper_create_buffer_with_content(initial_content);

    // Artificially reduce buffer size to force resize
    buf->len = 3; // smaller than strlen("hello") + strlen("world") == 10

    // Prepare string to prepend
    char *to_prepend = "hello";

    // Simulate buffer_resize failure by temporarily replacing buffer_resize
    // Not allowed to mock, so we must rely on real buffer_resize.
    // To force failure, set buf->alloc to NULL and try to resize to a huge size.
    // But since we cannot mock, we can only test with real allocation failure.
    // So, set needed to a very large value to likely cause allocation failure.
    // Overwrite to_prepend with a very long string.
    size_t huge_len = 1024 * 1024 * 1024; // 1GB
    char *huge_str = malloc(huge_len);
    if (huge_str == NULL) {
        // If allocation fails, skip the test as we cannot force buffer_resize to fail without mocking
        helper_cleanup_buffer(buf);
        return;
    }
    memset(huge_str, 'A', huge_len - 1);
    huge_str[huge_len - 1] = '\0';

    // Test: call buffer_prepend, expecting failure (-1)
    int ret = buffer_prepend(buf, huge_str);
    assert(ret == -1);

    // Assert: buffer content remains unchanged
    helper_assert_buffer_content(buf, initial_content);

    // Cleanup
    free(huge_str);
    helper_cleanup_buffer(buf);
}

int main() {
    printf("Running unit_test_buffer_prepend_resize_fails...
");
    unit_test_buffer_prepend_resize_fails();
    printf("unit_test_buffer_prepend_resize_fails PASSED
");
    return 0;
}


